//! Wire schema. One JSON object per envelope; `payload` and `sig` are base64.

use base64::Engine as _;
use base64::engine::general_purpose::STANDARD as B64;
use serde::{Deserialize, Deserializer, Serialize, Serializer};

use crate::crypto::DeviceCard;
use crate::{Result, SignalError};

pub const VERSION: u8 = 1;
/// `from` value of envelopes generated by the cloud lobby itself.
pub const SERVER: &str = "server";

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Kind {
    Hello,
    Offer,
    Answer,
    Candidate,
    Renegotiate,
    Bye,
    SessionCreate,
    SessionList,
    SessionJoin,
    SessionLeave,
    Sessions,
    MemberJoined,
    MemberLeft,
    Error,
}

impl Kind {
    /// Peer-addressed kinds are encrypted to the recipient (§5).
    pub fn is_peer_addressed(self) -> bool {
        matches!(self, Kind::Offer | Kind::Answer | Kind::Candidate | Kind::Renegotiate | Kind::Bye)
    }
    pub fn as_str(self) -> &'static str {
        match self {
            Kind::Hello => "hello",
            Kind::Offer => "offer",
            Kind::Answer => "answer",
            Kind::Candidate => "candidate",
            Kind::Renegotiate => "renegotiate",
            Kind::Bye => "bye",
            Kind::SessionCreate => "session_create",
            Kind::SessionList => "session_list",
            Kind::SessionJoin => "session_join",
            Kind::SessionLeave => "session_leave",
            Kind::Sessions => "sessions",
            Kind::MemberJoined => "member_joined",
            Kind::MemberLeft => "member_left",
            Kind::Error => "error",
        }
    }
}

fn b64_ser<S: Serializer>(v: &[u8], s: S) -> std::result::Result<S::Ok, S::Error> {
    s.serialize_str(&B64.encode(v))
}
fn b64_de<'de, D: Deserializer<'de>>(d: D) -> std::result::Result<Vec<u8>, D::Error> {
    let s = String::deserialize(d)?;
    B64.decode(s).map_err(serde::de::Error::custom)
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Envelope {
    pub v: u8,
    pub from: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub to: Option<String>,
    pub seq: u64,
    pub ts_ms: u64,
    pub kind: Kind,
    /// DTLS fingerprint of the SDP inside (offer/answer only), covered by the signature.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub fp: Option<String>,
    /// Session the message belongs to (routing hint for the cloud Session DO).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub sid: Option<String>,
    #[serde(serialize_with = "b64_ser", deserialize_with = "b64_de")]
    pub payload: Vec<u8>,
    #[serde(default, serialize_with = "b64_ser", deserialize_with = "b64_de")]
    pub sig: Vec<u8>,
}

impl Envelope {
    /// Bytes covered by the Ed25519 signature: v | from | to | seq | ts | kind | fp | sid | payload,
    /// each variable-length field length-prefixed (u32 BE).
    pub fn signed_bytes(&self) -> Vec<u8> {
        fn put(out: &mut Vec<u8>, b: &[u8]) {
            out.extend_from_slice(&(b.len() as u32).to_be_bytes());
            out.extend_from_slice(b);
        }
        let mut out = Vec::with_capacity(self.payload.len() + 256);
        out.extend_from_slice(b"callxl-sig-v1");
        out.push(self.v);
        put(&mut out, self.from.as_bytes());
        put(&mut out, self.to.as_deref().unwrap_or("").as_bytes());
        out.extend_from_slice(&self.seq.to_be_bytes());
        out.extend_from_slice(&self.ts_ms.to_be_bytes());
        put(&mut out, self.kind.as_str().as_bytes());
        put(&mut out, self.fp.as_deref().unwrap_or("").as_bytes());
        put(&mut out, self.sid.as_deref().unwrap_or("").as_bytes());
        put(&mut out, &self.payload);
        out
    }

    pub fn to_bytes(&self) -> Vec<u8> {
        serde_json::to_vec(self).expect("envelope serialises")
    }

    pub fn from_bytes(b: &[u8]) -> Result<Self> {
        let e: Envelope = serde_json::from_slice(b).map_err(|e| SignalError::Malformed(e.to_string()))?;
        if e.v != VERSION {
            return Err(SignalError::Malformed(format!("unsupported version {}", e.v)));
        }
        Ok(e)
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct SessionInfo {
    pub id: String,
    #[serde(default)]
    pub name: Option<String>,
    /// Signing keys (hex) of current members.
    #[serde(default)]
    pub members: Vec<String>,
    #[serde(default)]
    pub created_ms: u64,
}

/// Decoded payloads. Each kind has exactly one payload shape.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum Payload {
    Hello(HelloPayload),
    Sdp(SdpPayload),
    Candidate(CandidatePayload),
    Text(TextPayload),
    Sessions(SessionsPayload),
    Session(SessionRef),
    Member(MemberPayload),
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct HelloPayload {
    pub card: DeviceCard,
    /// LAN: sessions this device is a member of (for discovery over direct TCP).
    #[serde(default)]
    pub sessions: Vec<SessionInfo>,
    /// LAN: TCP port this device accepts signaling connections on.
    #[serde(default)]
    pub lan_port: Option<u16>,
    /// Whether the sender wants a hello back (first message on a connection).
    #[serde(default)]
    pub reply: bool,
    /// Random per process start: a new value means the device restarted.
    #[serde(default)]
    pub instance: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct SdpPayload {
    pub sdp: String,
    #[serde(default)]
    pub ice_restart: bool,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct CandidatePayload {
    pub mid: String,
    pub mline_index: i32,
    pub candidate: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct TextPayload {
    #[serde(default)]
    pub reason: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct SessionsPayload {
    pub list: Vec<SessionInfo>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct SessionRef {
    pub id: String,
    #[serde(default)]
    pub name: Option<String>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct MemberPayload {
    pub session: String,
    pub key: String,
    #[serde(default)]
    pub card: Option<DeviceCard>,
}

pub fn encode<T: Serialize>(p: &T) -> Vec<u8> {
    serde_json::to_vec(p).expect("payload serialises")
}

pub fn decode<T: for<'de> Deserialize<'de>>(b: &[u8]) -> Result<T> {
    serde_json::from_slice(b).map_err(|e| SignalError::Malformed(e.to_string()))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn envelope_roundtrip_json() {
        let e = Envelope {
            v: VERSION,
            from: "aa".into(),
            to: Some("bb".into()),
            seq: 7,
            ts_ms: 9,
            kind: Kind::SessionJoin,
            fp: None,
            sid: Some("s1".into()),
            payload: b"{\"id\":\"s1\"}".to_vec(),
            sig: vec![1, 2, 3],
        };
        let b = e.to_bytes();
        let s = String::from_utf8(b.clone()).unwrap();
        assert!(s.contains("\"kind\":\"session_join\""));
        assert_eq!(Envelope::from_bytes(&b).unwrap(), e);
    }
}
